mapper.select:
select idbitacora, idusuario, bitacora, bitacoras.fecha, hora
from seguridad.bitacoras join seguridad.usuarios using(idusuario)
where concat(bitacora, usuario) ilike '%'||#{termino}||'%'
order by fecha desc, hora desc
limit #{cantidad} offset #{pagina}

select count(idbitacora)
from seguridad.bitacoras join seguridad.usuarios using(idusuario)
where concat(bitacora, usuario) ilike '%'||#{termino}||'%'

select idbitacora, idusuario, bitacora, fecha, hora
from seguridad.bitacoras
where idbitacora=#{id}
